using Namaa.Domain.Entities;namespace Namaa.Application.PaymentVouchers.Dtos;public sealed record PaymentVoucherAllocationDto(long Id,long PaymentVoucherId,long PurchaseInvoiceId,decimal AllocatedAmount,DateTime CreatedAt){internal static PaymentVoucherAllocationDto FromEntity(PaymentVoucherAllocation e)=>new(e.Id,e.PaymentVoucherId,e.PurchaseInvoiceId,e.AllocatedAmount,e.CreatedAt);}public sealed record PaymentVoucherDto(long Id,string VoucherNumber,long? SupplierId,string? BeneficiaryName,long? ProjectId,DateTime VoucherDate,string PaymentMethod,decimal Amount,string? ReferenceNumber,string Status,string? Notes,long PaidByUserId,long? PostedByUserId,DateTime? PostedAt,DateTime CreatedAt,DateTime? UpdatedAt,IReadOnlyList<PaymentVoucherAllocationDto> Allocations){internal static PaymentVoucherDto FromEntity(PaymentVoucher e)=>new(e.Id,e.VoucherNumber,e.SupplierId,e.BeneficiaryName,e.ProjectId,e.VoucherDate,e.PaymentMethod,e.Amount,e.ReferenceNumber,e.Status,e.Notes,e.PaidByUserId,e.PostedByUserId,e.PostedAt,e.CreatedAt,e.UpdatedAt,e.Allocations.Select(PaymentVoucherAllocationDto.FromEntity).ToList());}
